const piles: Pile[] = ['drawPile', 'discardPile', 'exhaustPile'];
const pileKey = (pile: Pile) => `pile.${pile.replace('Pile', '')}`;
const seed = () => Math.floor(Math.random() * 4294967296);
const storeCards = content.cards.filter(card => card.rarity !== 'Starter');
const initialCollection = content.startingDeck.reduce<Record<string, number>>((all, id) => ({ ...all, [id]: (all[id] ?? 0) + 1 }), {});
const leaderArtKey: Record<LeaderId, string> = { fox: 'fox', warden: 'lanternstone', oracle: 'runebound' };
type Mode = 'map' | 'battle' | 'reward' | 'shop' | 'deck' | 'camp' | 'event' | 'loadout';
type Profile = { gold: number; health: number; unlocked: number; mapPosition: number; collection: Record<string, number>; deck: string[]; relicIds: RelicId[]; leader: LeaderId; difficulty: number; upgrades: Record<string, number>; equipmentOwned: EquipmentId[]; equipmentSlots: Partial<Record<EquipmentSlot, EquipmentId>>; runeInventory: Partial<Record<RuneId, number>>; cardRunes: Partial<Record<string, RuneId>> };
const chapterNames = { en: ['Mistwood','Ember Delta','Thunder Peaks','Stone Citadel','Thorn Wilds','Spirit Tide','Jade Sanctuary','Mirage Expanse','Fury Caldera','Worldforge'], 'zh-Hans': ['雾林','烬河三角洲','雷鸣群峰','岩甲城塞','荆棘荒野','万灵潮汐','翠玉圣域','幻雾长原','怒焰火山','万象熔炉'] } as const;
